"""Instruction data for the CustomVoice arms, generated by the untrained CustomVoice.

R (replay):  presets vivian / serena / uncle_fu x {no instruct + 5 instructs}; keeps the
             instruction-following the fine-tune would otherwise forget (on-policy replay).
P (pseudo):  our 14 characters (locked rows written into CustomVoice, as in D2) x the three
             evaluated emotions; after filtering, teaches "our row + instruction".
Texts: train-split lines whose real delivery emotion2vec calls neutral (its one reliable
label, D4 precision 0.94), 8-40 CJK characters, no Latin or digits. Never a val/test line
or one of the 30 eval probes. Seeded.

    python eval/rp_generate.py
Output: <WORK>/rp/{R,P}/<n>.wav and <WORK>/rp/index.jsonl (resumable by batch)
"""
from __future__ import annotations

import json
import re
import sys
from pathlib import Path

import numpy as np
import soundfile as sf

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "build"))
import common as C  # noqa: E402

PRESETS = ["vivian", "serena", "uncle_fu"]
R_INSTRUCTS = ["", "用开心的语气说", "用生气的语气说", "用伤心的语气说", "用惊讶的语气说", "小声地说"]
P_INSTRUCTS = ["用开心的语气说", "用生气的语气说", "用伤心的语气说"]
R_TEXTS_PER = 90           # per (preset, instruct)
P_TEXTS_PER = 30           # per (character, instruct)
ROW0 = 3020
KW = dict(max_new_tokens=400, non_streaming_mode=True)
BATCH = 24


def text_pool() -> list[str]:
    probes = {t.strip() for t in (Path(__file__).parent / "probes_neutral_zh.txt").read_text(encoding="utf-8").splitlines()}
    heldout = set()
    man = [json.loads(l) for l in (C.WORK / "manifest.jsonl").open(encoding="utf-8")]
    for r in man:
        if r["split"] != "train":
            heldout.add(r["text"])
    pool = set()
    for r in man:
        e = r.get("e2v") or {}
        t = r["text"]
        if (r["split"] == "train" and e and max(e, key=e.get) == "neutral" and e["neutral"] >= 0.6
                and 8 <= C.cjk_count(t) <= 40 and not re.search(r"[A-Za-z0-9]", t)
                and t not in heldout and t not in probes):
            pool.add(t)
    return sorted(pool, key=lambda t: C.stable_unit("rp:" + t))


def make_plan() -> list:
    texts = text_pool()
    print(f"[rp] {len(texts)} candidate texts")
    jobs = []      # (set, speaker, instruct, [texts]); texts taken cyclically from the pool
    k = 0

    def take(n):
        nonlocal k
        out = [texts[(k + i) % len(texts)] for i in range(n)]
        k = (k + n) % len(texts)
        return out
    for spk in PRESETS:
        for ins in R_INSTRUCTS:
            jobs.append(("R", spk, ins, take(R_TEXTS_PER)))
    for spk in C.ROSTER:
        for ins in P_INSTRUCTS:
            jobs.append(("P", spk, ins, take(P_TEXTS_PER)))
    return jobs


def generate(jobs: list, cv_path: str, table_path: str, out: Path) -> None:
    import torch
    from qwen_tts import Qwen3TTSModel

    idx_path = out / "index.jsonl"
    done = set()
    if idx_path.exists():
        done = {(r["set"], r["speaker"], r["instruct"]) for r in map(json.loads, idx_path.read_text(encoding="utf-8").splitlines())}

    cv = Qwen3TTSModel.from_pretrained(cv_path, dtype=torch.bfloat16, device_map="cuda:0")
    tc = cv.model.config.talker_config
    emb = cv.model.talker.model.codec_embedding.weight
    table = torch.load(table_path)
    roster = table["names"]
    with torch.no_grad():
        for i, name in enumerate(roster):
            row = ROW0 + i
            assert row not in set(tc.spk_id.values()), row
            emb[row] = table["table"][i].to(emb.device, emb.dtype)
            tc.spk_id[name] = row
            tc.spk_is_dialect[name] = False
    for j, (st, spk, ins, ts) in enumerate(jobs):
        if (st, spk, ins) in done:
            continue
        wavs = []
        for b in range(0, len(ts), BATCH):           # 16 GB card: a 90-clip KV cache spills to host memory
            torch.manual_seed(5000 + 100 * j + b)
            tb = ts[b:b + BATCH]
            wb, sr = cv.generate_custom_voice(text=tb, speaker=[spk] * len(tb), language=["Chinese"] * len(tb),
                                              instruct=[ins] * len(tb) if ins else None, **KW)
            wavs += wb
        (out / st).mkdir(parents=True, exist_ok=True)
        with idx_path.open("a", encoding="utf-8") as f:
            for n, (t, w) in enumerate(zip(ts, wavs)):
                p = out / st / f"{st}{j:03d}_{n:03d}.wav"
                sf.write(p, np.asarray(w, dtype=np.float32), sr, subtype="PCM_16")
                dur = len(w) / sr
                f.write(json.dumps({"set": st, "speaker": spk, "instruct": ins, "text": t,
                                    "id": p.stem, "audio": str(p.relative_to(out)).replace("\\", "/"), "dur": round(dur, 3),
                                    "runaway": bool(dur * 12.5 >= 399 or dur > 5 * len(re.findall(r"[一-鿿]", t)) / 4.5)},
                                   ensure_ascii=False) + "\n")
        print(f"[rp] {st} {spk} {ins or '-'}: {len(ts)}", flush=True)


if __name__ == "__main__":
    import argparse
    ap = argparse.ArgumentParser()
    ap.add_argument("--plan", help="write the job list (texts per job) to this json; needs the local manifest")
    ap.add_argument("--from_plan", help="generate from this job list")
    ap.add_argument("--cv", help="CustomVoice model dir")
    ap.add_argument("--table", help="speaker_table.pt")
    ap.add_argument("--out", help="output dir")
    ap.add_argument("--batch", type=int, default=BATCH)
    a = ap.parse_args()
    if a.plan:
        Path(a.plan).write_text(json.dumps(make_plan(), ensure_ascii=False), encoding="utf-8")
        print("[rp] plan written:", a.plan)
    else:
        BATCH = a.batch
        generate(json.loads(Path(a.from_plan).read_text(encoding="utf-8")), a.cv, a.table, Path(a.out))
